    final p = Path();
    var i = 0;
    while (i < d.length) {
      switch (d[i++].toInt()) {
        case 0:
          p.moveTo(d[i], d[i + 1]);
          i += 2;
        case 1:
          p.lineTo(d[i], d[i + 1]);
          i += 2;
        case 2:
          p.cubicTo(d[i], d[i + 1], d[i + 2], d[i + 3], d[i + 4], d[i + 5]);
          i += 6;
        default:
          p.close();
      }
    }
    return p;
  }

